INSERT INTO ti_risk_reference_catalog
  (code,group_name,title,scenario,review_guidance,control_options,version)
VALUES
  ('DNS_LAYANAN','Infrastruktur dan jaringan','Gangguan resolusi DNS','Kesalahan DNS internal atau eksternal dapat menghambat akses ke layanan TI meskipun jaringan utama masih terhubung.','Tinjau konfigurasi resolver, perubahan DNS, histori kegagalan, dan monitoring nama domain.','Kelola DNS cadangan, uji resolusi layanan penting, dan catat perubahan konfigurasi.','1.1'),
  ('SERTIFIKAT_TLS','Keamanan komunikasi','Sertifikat TLS kedaluwarsa','Sertifikat digital layanan yang berakhir masa berlaku dapat menyebabkan koneksi ditolak dan melemahkan kepercayaan sistem.','Periksa inventaris sertifikat, masa berlaku, rantai kepercayaan, dan penanggung jawab pembaruan.','Pantau kedaluwarsa, uji pembaruan sebelum produksi, dan verifikasi konfigurasi TLS.','1.1'),
  ('DOMAIN_KEDALUWARSA','Ketergantungan digital','Masa berlaku domain layanan terlewat','Nama domain organisasi yang tidak diperpanjang dapat menghentikan layanan web, email, atau integrasi sistem.','Tinjau daftar domain, tanggal kedaluwarsa, hak akses registrar, dan pemilik administrasi.','Terapkan pengingat masa berlaku serta kepemilikan registrar yang dikelola lembaga.','1.1'),
  ('WAKTU_SISTEM','Integritas data','Ketidaksesuaian sinkronisasi waktu','Perbedaan waktu antarserver dan perangkat dapat mengganggu urutan transaksi, audit log, dan validitas sertifikat.','Bandingkan waktu sistem, sumber NTP, zona waktu, dan log sinkronisasi.','Gunakan sumber waktu yang disetujui, monitoring drift, dan pemeriksaan waktu pada insiden.','1.1'),
  ('KAPASITAS_DATABASE','Layanan core banking','Pertumbuhan database melampaui kapasitas','Pertumbuhan data atau indeks tanpa pemantauan dapat memperlambat transaksi dan meningkatkan risiko gangguan layanan.','Periksa tren penyimpanan, pertumbuhan tabel, performa query, dan ambang kapasitas.','Gunakan capacity planning, pengujian restore, serta pemeliharaan database terjadwal.','1.1'),
  ('AKUN_ISTIMEWA','Akses dan identitas','Akun istimewa tanpa pengawasan memadai','Kewenangan administratif yang tidak dibatasi dapat meningkatkan dampak kesalahan dan akses tidak sah.','Tinjau daftar admin, penggunaan akun bersama, aktivitas sensitif, dan proses persetujuan.','Batasi privilege, pisahkan akun administratif, dan tinjau aktivitas secara berkala.','1.1'),
  ('PENGIRIMAN_SALAH','Data dan privasi','Salah alamat pengiriman informasi','Dokumen atau data sensitif dapat terkirim kepada pihak yang tidak berhak melalui email atau kanal pesan.','Periksa kebijakan klasifikasi data, verifikasi penerima, dan riwayat salah kirim.','Gunakan verifikasi penerima, pembatasan lampiran, dan kanal pertukaran yang aman.','1.1'),
  ('PEMULIHAN_KREDENSIAL','Akses dan identitas','Proses reset akun disalahgunakan','Verifikasi identitas yang lemah saat pemulihan akun dapat memungkinkan pengambilalihan akses pengguna.','Periksa autentikasi saat reset, approval, catatan helpdesk, dan perubahan faktor autentikasi.','Terapkan verifikasi berlapis serta pemberitahuan dan audit aktivitas pemulihan akun.','1.1'),
  ('PROTEKSI_API','Integrasi sistem','Penyalahgunaan antarmuka API','API yang tidak memvalidasi otorisasi, volume, atau duplikasi permintaan berpotensi mengekspos data dan mengganggu transaksi.','Uji kontrol autentikasi, RBAC, idempotency, rate limit, dan pemantauan permintaan.','Terapkan pembatasan akses, pengendalian permintaan, dan pencatatan anomali API.','1.1'),
  ('INTEGRITAS_SLIK','Pelaporan dan integrasi','Ketidaksesuaian data pelaporan kredit','Perbedaan data kredit antara sumber CBS dan berkas pelaporan dapat memicu koreksi, penolakan, atau keterlambatan laporan.','Tinjau rekonsiliasi sumber data, hasil validasi, proses koreksi, dan bukti pengiriman.','Terapkan validasi data dan peninjauan selisih sebelum serta sesudah pengiriman.','1.1'),
  ('KUNCI_ENKRIPSI','Kriptografi','Kunci enkripsi tidak terkelola','Kehilangan, kebocoran, atau perubahan kunci enkripsi tanpa tata kelola dapat menghambat pemulihan dan kerahasiaan data.','Tinjau penyimpanan kunci, hak akses, backup kunci, rotasi, serta prosedur pemulihan.','Tetapkan pemilik kunci, rotasi terkontrol, dan uji pemulihan enkripsi.','1.1'),
  ('LOG_RETENSI','Pemantauan dan audit','Retensi log tidak mencukupi','Log yang dihapus terlalu dini dapat menghambat penelusuran transaksi dan investigasi insiden.','Periksa jenis log, lokasi penyimpanan, kebijakan retensi, dan integritas akses arsip.','Terapkan retensi yang ditetapkan lembaga, perlindungan akses, serta monitoring kapasitas.','1.1'),
  ('UJI_PERUBAHAN','Perubahan dan operasional','Perubahan produksi tanpa persetujuan','Penerapan konfigurasi atau aplikasi tanpa persetujuan berpotensi menyebabkan kegagalan transaksi dan sulit dipulihkan.','Periksa tiket perubahan, UAT, pihak yang menyetujui, waktu deployment, dan rollback.','Gunakan pengendalian perubahan dengan pemisahan tugas dan pengujian regresi.','1.1'),
  ('KERENTANAN_ASET','Keamanan siber','Aset terlupakan dari pemindaian keamanan','Perangkat atau layanan yang tidak masuk inventaris dapat luput dari patching, pengawasan, dan pengujian keamanan.','Bandingkan inventaris, cakupan pemindaian, daftar layanan, dan hasil pembaruan.','Sinkronkan inventaris dengan pemindaian berkala dan proses penanganan temuan.','1.1'),
  ('HAK_AKSES_FISIK','Keamanan fisik','Akses fisik ruang infrastruktur tidak tercatat','Pihak yang tidak berwenang dapat memperoleh akses ke perangkat kritis apabila kontrol pintu dan pengunjung lemah.','Tinjau daftar akses ruangan, rekaman kunjungan, CCTV, dan pencabutan kartu akses.','Kelola daftar akses fisik, pengunjung, serta peninjauan berkala.','1.1'),
  ('DR_SITE_GAGAL','Kelangsungan layanan','Lokasi pemulihan alternatif tidak siap','Rencana failover dapat gagal ketika lokasi cadangan, data, atau koneksi tidak dapat digunakan pada saat bencana.','Periksa kesiapan site cadangan, hasil uji, ketergantungan vendor, dan capaian target pemulihan.','Uji aktivasi alternatif secara terjadwal dan perbaiki selisih hasil terhadap target.','1.1')
INSERT INTO ti_risk_reference_register(institution_id,reference_code)
